import { defineConfig } from "@loom/app";
import { retryMiddleware } from "@loom/middleware";
import { sqliteStorage } from "@loom/plugin-sqlite";
import type { ResumeAuthenticator } from "@loom/workflow-runtime";
// AUTO-GENERATED by `loom gen` from app/flows/**/flow.ts — the folder convention,
// resolved at BUILD time (static imports), so the flow set is identical on every
// resume / remote worker. Run `pnpm gen` after adding a flow.
import { flowModules } from "../app/loom.gen";

export type LoomApp = ReturnType<typeof defineConfig>;

// `surface(ctx).*` in a flow targets the default A2UI surface, "ui".
export const SURFACES = ["ui"];

/**
 * K12 — who may reopen a suspended execution.
 *
 * The `release-approval` flow suspends on a human decision, and a resume event
 * arrives from OUTSIDE the process. Without an authenticator the kernel accepts
 * any `ApprovalGranted` it is handed, so the gate is closed by whoever remembers
 * to check rather than by the runtime.
 *
 * This stand-in accepts a known approver list, deterministically so replays stay
 * stable. Replace it with signature or session verification — the seam is the
 * point, not the list. Pre-flight verification (`checks.verify` below) errors on
 * a flow that declares resume gates with nothing wired here.
 */
const APPROVERS = new Set(["release-manager", "on-call"]);

export const approvalAuthenticator: ResumeAuthenticator = {
  verify(event) {
    if (event.eventType !== "ApprovalGranted") return { status: "not-applicable" };
    const approvedBy = (event.payload as { approvedBy?: unknown })?.approvedBy;
    if (typeof approvedBy !== "string" || !APPROVERS.has(approvedBy)) {
      return { status: "rejected", reason: `"${String(approvedBy)}" is not an approver` };
    }
    return { status: "verified", actor: approvedBy, verifiedBy: "approver-list" };
  },
};

export type StorageOpt = { kind: "memory" } | { kind: "sqlite"; dir: string; branching?: boolean };

/**
 * The composition root. `defineConfig` assembles the durable runtime, stores,
 * effect middleware, projection runtime, and A2A bus from this static config and
 * returns a `LoomApp` — you still have direct access to every primitive
 * (`app.runtime`, `app.stores`, `app.projectionRuntime`, …).
 */
export function buildApp(opts?: { storage?: StorageOpt }): LoomApp {
  return defineConfig({
    storage:
      opts?.storage?.kind === "sqlite"
        ? sqliteStorage({ dir: opts.storage.dir, branching: opts.storage.branching === true })
        : { kind: "memory" },
    surfaces: SURFACES,
    // Flows discovered by the folder convention (see the import above).
    flowModules,
    // Cross-cutting effect concerns as a composable chain — every effect (each
    // step's handler) is wrapped with exponential backoff + deterministic jitter.
    execution: {
      effectMiddleware: [
        retryMiddleware({ maxRetries: 3, baseDelayMs: 50, factor: 2, jitter: true }),
      ],
    },
    security: { resumeAuthenticator: approvalAuthenticator },
    // Static flow-graph checks at boot (missing effects, dangling capabilities),
    // plus the pre-flight rule set (@loom/verify): determinism, replay-safety,
    // suspension-safety, capability-compat, effect-class, and the rest.
    //
    // "warn" rather than "error" so a new project is never blocked by a finding
    // it has not read yet; `loom doctor` prints the same report on demand, and
    // `loom verify --config` exits non-zero for CI.
    checks: { validate: "warn", verify: "warn" },
  });
}
